/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"bassstation-level-17","number":17,"title":"Complete On-Key Functions, Micro-Tuning & Custom Greeting","skillBand":"Textbook","duration":"From the course textbook","summary":"- Master the standardized On-Key editing workflow, parameter value adjustments, and the 10-second automatic exit timeout. - Calibrate continuous Modulation Wheel routing depths across all four primary destinations (-63 to +63).","modules":[{"id":"bassstation-m-17-1","code":"17","title":"Complete On-Key Functions, Micro-Tuning & Custom Greeting","blurb":"- Master the standardized On-Key editing workflow, parameter value adjustments, and the 10-second automatic exit timeout. - Calibrate continuous Modulation Wheel routing depths across all four primary destinations (-63 to +63).","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"bassstation-l-o-17","title":"Section overview","blocks":[{"type":"step","title":"Section 17.1 — Master Faceplate On-Key Function Catalogue","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Master the standardized On-Key editing workflow, parameter value adjustments, and the 10-second automatic exit timeout.","Calibrate continuous Modulation Wheel routing depths across all four primary destinations (-63 to +63).","Configure Channel Aftertouch routing depths across Filter Frequency, LFO 1 Vibrato, and LFO 2 Speed (-63 to +63).","Program Velocity sensitivity curves for Amplitude and Modulation envelopes (-63 to +63).","Calibrate the pre-output <strong>VCA Limiter</strong> (0 to 127) for output dynamics protection.","Manage global parameters: Master Tune (±50 cents), Global MIDI Channel (1–16), Input Gain, and SysEx Patch Dumps.","Master the comprehensive multi-press gesture catalogue."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-17-1-1","title":"17.1.1: Standard On-Key Operational Workflow","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II utilizes its 25 physical piano keys as a primary digital programming interface for secondary parameters printed directly above the keybed."},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                      STANDARD ON-KEY EDITING PROTOCOL\n   [Step 1] Press [Function / Exit] ──► Enters Function Mode (Display Shows Value)\n   [Step 2] Press Target Key on Keybed (e.g., Mod Wh: Filter Freq)\n   [Step 3] Adjust Parameter Value via [Patch / Value ▲ and ▼]\n   [Step 4] Press [Function / Exit] ──► Exits Function Mode (Commits to Buffer)\n   \n   *Automatic Timeout*: If no controls are touched for 10 seconds, the\n   synthesizer automatically exits Function Mode and returns to play mode.</pre>"}]}],"minutes":8},{"id":"bassstation-l-17-1-2","title":"17.1.2: Modulation Wheel Destination Depths","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Modulation Wheel (MIDI CC 1) can be routed independently to four internal destinations via dedicated keys in the lower octave:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    MODULATION WHEEL ON-KEY DESTINATIONS                    │\n├───────────────┬───────────────────────────┬────────────────┬───────────────┤\n│ Key Label     │ Physical Key Note         │ Value Range    │ Default Value │\n├───────────────┼───────────────────────────┼────────────────┼───────────────┤\n│ Filter Freq   │ Lowest `C` (Key 1)        │ `-63` to `+63` │ `0`           │\n│ LFO 1 to Osc  │ Lowest `C#` (Key 2)       │ `-63` to `+63` │ `0`           │\n│ LFO 2 to Filt │ Lowest `D#` (Key 4)       │ `-63` to `+63` │ `0`           │\n│ Osc 2 Pitch   │ Lowest `F` (Key 6)        │ `-63` to `+63` │ `0`           │\n└───────────────┴───────────────────────────┴────────────────┴───────────────┘</pre>"},{"type":"list","items":["Bipolar scaling: Positive values increase modulation depth as the wheel is pushed forward; negative values invert the modulation response."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-17-1-3","title":"17.1.3: Channel Aftertouch Destination Depths","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Channel Aftertouch (keybed downward pressure) provides expressive real-time control routed via keys in the lower octave:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                      AFTERTOUCH ON-KEY DESTINATIONS                        │\n├───────────────┬───────────────────────────┬────────────────┬───────────────┤\n│ Key Label     │ Physical Key Note         │ Value Range    │ Default Value │\n├───────────────┼───────────────────────────┼────────────────┼───────────────┤\n│ Filter Freq   │ Lowest `E` (Key 5)        │ `-63` to `+63` │ `0`           │\n│ LFO 1 to Osc  │ Lowest `F#` (Key 7)       │ `-63` to `+63` │ `0`           │\n│ LFO 2 Speed   │ Lowest `G#` (Key 9)       │ `-63` to `+63` │ `0`           │\n└───────────────┴───────────────────────────┴────────────────┴───────────────┘</pre>"},{"type":"list","items":["<strong>LFO 2 Speed Routing</strong>: Pushing down on the keybed accelerates the rate of LFO 2, allowing dramatic speed increases on filter sweeps or PWM without taking hands off the keyboard."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-17-1-4","title":"17.1.4: Velocity Sensitivity Calibration","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"Key strike velocity (0–127) can dynamically modulate envelope attack intensity and maximum amplitude:"},{"type":"list","items":["<strong>Amp Env Velocity (<code>Function</code> + Middle <code>C#</code>)</strong>:","Range: <strong><code>-63</code> to <code>+63</code></strong> (Default = <code>0</code>).","Positive values scale overall note volume in proportion to strike velocity.","<em>Authoritative Production Tip</em>: A value of <strong><code>+40</code></strong> provides the most natural, expressive dynamic response for acoustic and keyboard performance.","<strong>Mod Env Velocity (<code>Function</code> + Middle <code>D#</code>)</strong>:","Range: <strong><code>-63</code> to <code>+63</code></strong> (Default = <code>0</code>).","Scales the depth of all Modulation Envelope routings (Filter Cutoff, Pitch Sweeps, PWM) based on key velocity."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-1-5","title":"17.1.5: Pre-Output VCA Limiter","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Circuit Dynamics</strong>:","The <strong>VCA Limiter</strong> (<code>Function</code> + Middle <code>D</code>) is a digital output dynamics control that limits maximum analog signal excursions entering the output buffer.","Range: <strong><code>0</code> to <code>127</code></strong> (0 = Limiter fully active / maximum squash; 127 = Limiter completely open / bypassed).","<strong>Production Workflow</strong>:","Always adjust the VCA Limiter as the <strong>final step</strong> in your sound design process.","If high resonance or stacked oscillator overdrive causes unmanageable output level spikes, lower the Limiter value to stabilize output levels."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-1-6","title":"17.1.6: Global System On-Key Parameters","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The upper octave keys govern global hardware parameters:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    GLOBAL SYSTEM ON-KEY FUNCTIONS                          │\n├───────────────┬───────────────────────────┬────────────────┬───────────────┤\n│ Function      │ Physical Key Note         │ Range / Format │ Persistence   │\n├───────────────┼───────────────────────────┼────────────────┼───────────────┤\n│ Global Tune   │ Upper `A#` (Key 23)       │ `-50` to `+50` │ SAVED at boot │\n│ Global Channel│ Upper `G#` (Key 21)       │ `1` to `16`    │ SAVED at boot │\n│ Local Control │ Upper `A` (Key 22)        │ `On` / `OFF`   │ NOT SAVED     │\n│ Input Gain    │ Upper `C` (Key 13)        │ `-10` to `+60` │ SAVED at boot │\n│ SysEx Dump    │ Highest `C` (Key 25)      │ `OnE` / `All`  │ Instant SysEx │\n└───────────────┴───────────────────────────┴────────────────┴───────────────┘</pre>"},{"type":"list","items":["<strong>Global Tune</strong>: Offsets master concert pitch across ±50 cents (1 semitone) to tune to acoustic instruments (e.g., pianos tuned to A=442 Hz or A=432 Hz).","<strong>SysEx Dump</strong>: Transmits the current patch (<code>OnE</code>) or the entire 128-patch non-volatile library (<code>All</code>) via MIDI SysEx out through USB and 5-Pin DIN."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-1-7","title":"17.1.7: Master Multi-Press Gesture Catalogue","blocks":[{"type":"step","title":"17.1.7: Master Multi-Press Gesture Catalogue","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"To access deep firmware features without adding dedicated faceplate buttons, the Bass Station II implements a standardized multi-press gesture system:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    MASTER MULTI-PRESS GESTURE CATALOGUE                    │\n├────────────────────┬─────────────────────────────┬─────────────────────────┤\n│ Firmware Feature   │ Physical On-Key Location    │ Required Gesture Count  │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Paraphonic Mode    │ Upper `D` (Osc 1-2 Sync)    │ Press key TWICE (`P-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Oscillator Error   │ Lower `D` (Pitch Bend Range)│ Press key TWICE (`E-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Filter Tracking    │ Upper `F` (Filter Freq)     │ Press key TWICE (`F-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Envelope Retrigger │ Lower `A#` / `B` (Amp/Mod)  │ Press key TWICE (`r-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Retrigger Count    │ Lower `A#` / `B` (Amp/Mod)  │ Press THREE Times (`c-x`)│\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Fixed Sustain      │ Lower `A#` / `B` (Amp/Mod)  │ Press FOUR Times (`d-x`)│\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Glide Divergence   │ Upper `C` (Input Gain)      │ Press key TWICE (`g-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ AFX Overlay Bank   │ Upper `F#` (Arp Swing)      │ Press key TWICE (`o-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Overlay Protect    │ Upper `G` (SEQ Retrig)      │ Press key TWICE (`r-x`) │\n├────────────────────┼─────────────────────────────┼─────────────────────────┤\n│ Tuning Table Select│ Upper `A#` (Global Tune)    │ Press key TWICE (`t-x`) │\n└────────────────────┴─────────────────────────────┴─────────────────────────┘</pre>"}]},{"type":"step","title":"Section 17.2 — Micro-Tuning Tables Architecture","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Understand the 9-table micro-tuning memory structure (<code>t-0</code> to <code>t-8</code>), identifying the non-volatile retention rule.","Select, audition, and save custom micro-tonal tuning tables on the physical hardware.","Identify and evaluate all eight factory-included historical and non-Western tuning scales.","Execute real-time tuning morphing during performance.","Deploy Novation Components and MIDI Tuning Standard (MTS) SysEx for custom scale integration."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-17-2-1","title":"17.2.1: Micro-Tuning Memory Structure (9 Tables, 8 Savable)","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II supports custom micro-tonal scale tuning across 9 internal table registers:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                    MICRO-TUNING TABLE MEMORY STRUCTURE                     │\n├───────────────┬────────────────────────────────────────────────────────────┤\n│ Table Index   │ Operating Behavior &amp; Volatility                            │\n├───────────────┼────────────────────────────────────────────────────────────┤\n│ Table `t-0`   │ Standard 12-Tone Equal Temperament (12-TET). Volatile:     │\n│               │ Automatically re-initializes to 12-TET on startup.         │\n├───────────────┼────────────────────────────────────────────────────────────┤\n│ Tables `t-1`  │ Custom Micro-Tuning Tables. Non-Volatile: Saved in EEPROM  │\n│ through `t-8` │ and preserved across power cycles when saved.              │\n└───────────────┴────────────────────────────────────────────────────────────┘</pre>"},{"type":"list","items":["<strong>Sub-Cent Resolution</strong>:","The digital pitch DAC calculates micro-tonal pitch intervals with an internal resolution of 256 steps per semitone (~0.39 cents precision), ensuring flawless mathematical scale reproduction."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-2-2","title":"17.2.2: Selecting and Saving Tuning Tables","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Selection Gesture</strong>:","Press <strong>Function / Exit</strong>, then <strong>press the Global Tune key TWICE</strong> (the upper <code>A#</code> key).","Display indicates <code>t-0</code> through <code>t-8</code>. Adjust using <strong>Patch/Value ▲ and ▼</strong>.","<strong>Saving Custom Tables</strong>:","While on the tuning table selection menu, press <strong>Save</strong>.","The display flashes the active table number. Press <strong>Save</strong> again to commit the table to EEPROM."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-2-3","title":"17.2.3: Factory Included Tuning Scales","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"prose","html":"The Bass Station II includes eight pre-programmed historical, mathematical, and non-Western micro-tuning scales:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌────────────────────────────────────────────────────────────────────────────┐\n│                      FACTORY INCLUDED TUNING TABLES                        │\n├──────┬──────────────────────┬──────────────────────────────────────────────┤\n│ Slot │ Scale Name           │ Acoustic / Cultural Origin &amp; Character       │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-1`│ Prime                │ Mathematical harmonic series based on prime  │\n│      │                      │ integer frequency ratios.                    │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-2`│ Harmonic Series      │ Natural acoustic overtone series aligned to  │\n│      │ (432 Hz Reference)   │ A=432 Hz fundamental concert pitch.          │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-3`│ Indian Scale         │ Traditional 22-Shruti microtonal intervals;  │\n│      │                      │ authentic Indian classical raga intonation.  │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-4`│ Ptolemy Scale        │ Ancient Greek Just Intonation diatonic scale │\n│      │ (Just Intonation)    │ with pure, beat-free 3rds and 5ths.          │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-5`│ Chinese Bianzhong    │ Authentic interval tuning of ancient bronze  │\n│      │                      │ Bianzhong chime bells.                       │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-6`│ Turkish Scale        │ Traditional Ottoman/Turkish Makam micro-tonal│\n│      │                      │ quarter-tone comma intervals.                │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-7`│ Dan Schmidt Slendro  │ Authentic Indonesian Gamelan Slendro and     │\n│      │ / Pelog Tuning       │ Pelog metallophone scales.                   │\n├──────┼──────────────────────┼──────────────────────────────────────────────┤\n│ `t-8`│ Wendy Carlos Super   │ Non-octave repeating Just microtonal scale   │\n│      │ Just Intonation      │ engineered by synthesis pioneer Wendy Carlos.│\n└──────┴──────────────────────┴──────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"2. Hardware Verification & Practical Exercise","blocks":[{"type":"list","items":["Access the tuning menu (<code>Function</code> + double-tap upper <code>A#</code>); select <code>t-3</code> (Indian).","Play melodic lines up the keybed; hear authentic quarter-tone Shruti pitch intervals.","Switch to <code>t-0</code> to restore standard 12-TET tuning."],"ordered":true}]}],"minutes":8},{"id":"bassstation-l-17-2-4","title":"17.2.4: Real-Time Tuning Table Morphing","blocks":[{"type":"step","title":"17.2.4: Real-Time Tuning Table Morphing","blocks":[{"type":"heading","text":"1. Technical Exposition","level":4},{"type":"prose","html":"Because tuning tables can be switched in real time while notes are actively sustaining:"},{"type":"list","items":["Set <strong>Glide Time</strong> to 50%.","Play and hold a sustained paraphonic interval.","Access the tuning menu and step through <code>t-1</code> to <code>t-8</code>.","The internal DCOs will smoothly glide from one micro-tonal scale into the next in real time without audio dropouts."],"ordered":false}]},{"type":"step","title":"Section 17.3 — Custom Startup Greeting Message","blocks":[{"type":"heading","text":"Section Learning Outcomes","level":3},{"type":"list","items":["Program custom scrolling startup text messages across the 3-character 7-segment display.","Apply character set constraints (letters, numbers, hyphens) to 7-segment display geometry.","Manage greeting messages via Novation Components and standard SysEx strings."],"ordered":false}]}],"minutes":8},{"id":"bassstation-l-17-3-1","title":"17.3.1: Startup Greeting Architecture & Character Set","blocks":[{"type":"step","title":"1. Technical Exposition","blocks":[{"type":"list","items":["<strong>Display Mechanics</strong>:","The 3-character 7-segment LED display can scroll a custom ASCII alphanumeric text string upon power-on.","<strong>Supported Character Set</strong>:","Numbers: <code>0</code> to <code>9</code>.","Letters: <code>A</code> to <code>Z</code> and <code>a</code> to <code>z</code> (rendered using standard 7-segment approximations, e.g., <code>A</code>, <code>b</code>, <code>C</code>, <code>d</code>, <code>E</code>, <code>F</code>, <code>G</code>, <code>h</code>, <code>I</code>, <code>J</code>, <code>L</code>, <code>n</code>, <code>o</code>, <code>P</code>, <code>q</code>, <code>r</code>, <code>S</code>, <code>t</code>, <code>U</code>, <code>y</code>).","Punctuation: Spaces and hyphens (<code>-</code>).","<strong>Configuration via Components</strong>:","In Novation Components, navigate to the <strong>Startup Message</strong> page.","Enter your custom studio name or owner initials (e.g., <code>STUDIO-A-BS2</code>).","Click <strong>Send to Bass Station II</strong>.","Power cycle the unit; confirm your custom text scrolls across the screen on boot."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
